-- V69: Fresh CPU Component Catalog Seed
-- Intel: Core i3/i5/i7/i9 4th Gen -> 14th Gen + Core Ultra desktop
-- AMD: Ryzen 1000 -> 9000 desktop, APU/G/GE, mobile, PRO, Threadripper excluded
-- Local reset friendly: existing CPU catalog rows are removed first.
-- ============================================================

DELETE FROM hardware_components
WHERE component_type = 'CPU';

INSERT INTO hardware_components (
    component_type,
    category,
    brand_id,
    series_name,
    model_name,
    normalized_name,
    core_count,
    thread_count,
    extra_specs,
    verified,
    active
)
